from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[1]
base='https://ea-la.github.io'
profiles=[('LinkedIn','https://www.linkedin.com/in/elham-amini-745560302/'),('Instagram','https://www.instagram.com/___elham_amini___/'),('GitHub','https://github.com/EA-LA')]
projects=[('01','Finance World','Tools for the independent trader.','Trading calculators, finance lessons, market research and a journal in a connected web workspace.','https://www.fynxfinanceworld.com/'),('02','FYNX for iPhone','The toolkit, closer at hand.','Risk tools, market context and a trading routine built for iPhone.','https://site.fynxfinanceworld.com/'),('03','FYNX API','A developer-facing foundation.','Forex risk calculations and prop firm rule evaluation for software integrations.','https://www.fynxfinanceworld.com/api/'),('04','FYNX Funded','A process built around the rules.','Simulated trading evaluations, account objectives and risk limits. New purchases are currently paused.','https://www.fynxfunded.com/'),('05','FYNX Journal','Ideas with room to breathe.','Product explanations, trading routines and stories from the FYNX ecosystem.','https://blog.fynxfinanceworld.com/'),('06','The public roadmap','A direction for the long term.','The strategic vision for FYNX, from the trading foundation to a broader financial ecosystem.','https://roadmap.fynxfinanceworld.com/')]
pages=[]
def links():return ''.join(f'<a href="{u}">{n} <span aria-hidden="true">↗</span></a>' for n,u in profiles)
def projects_html():return ''.join(f'<a class="project" href="{u}"><span class="number">{n}</span><div><span class="eyebrow">{name}</span><h3>{title}</h3><p>{desc}</p></div><span class="project-arrow" aria-hidden="true">↗</span></a>' for n,name,title,desc,u in projects)
def page(file,title,description,body,kind='WebPage',private=False):
 url=base+('/' if file=='index.html' else '/'+file)
 person={'@type':'Person','@id':base+'/#person','name':'Elham Amini','url':base+'/','jobTitle':'Founder of FYNX','description':'Founder and product builder who started FYNX to help retail traders.','sameAs':[u for _,u in profiles]+['https://www.fynxfinanceworld.com/founder.html'],'worksFor':{'@id':'https://www.fynxfinanceworld.com/#organization'}}
 entity={'@type':kind,'@id':url+'#webpage','name':title,'description':description,'url':url,'isPartOf':{'@id':base+'/#website'}}
 if kind=='ProfilePage':entity['mainEntity']={'@id':base+'/#person'}
 if kind=='BlogPosting':entity.update(headline=title,author={'@id':base+'/#person'},publisher={'@id':base+'/#person'},mainEntityOfPage=url)
 graph=[person,{'@type':'Organization','@id':'https://www.fynxfinanceworld.com/#organization','name':'FYNX','url':'https://www.fynxfinanceworld.com/','founder':{'@id':base+'/#person'}},{'@type':'WebSite','@id':base+'/#website','name':'Elham Amini','url':base+'/','publisher':{'@id':base+'/#person'}},entity]
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if '/'+file==u else '')+f'>{label}</a>' for label,u in [('About','/about.html'),('Work','/work.html'),('Notes','/notes/why-i-started-fynx.html'),('Contact','/contact.html')])
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="robots" content="{'noindex,follow' if private else 'index,follow,max-image-preview:large'}"><meta name="theme-color" content="#f5f3eb"><link rel="canonical" href="{url}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="{'article' if kind=='BlogPosting' else 'website'}"><meta property="og:site_name" content="Elham Amini"><meta name="twitter:card" content="summary"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph}).replace('<',chr(92)+'u003c')}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header shell"><a class="wordmark" href="/" aria-label="Elham Amini home">ea<span>↗</span></a><nav aria-label="Main navigation">{nav}</nav><a class="header-fynx" href="https://www.fynxfinanceworld.com/">BUILDING FYNX ↗</a></header><main id="main">{body}</main><footer class="shell"><div class="footer-top"><a class="footer-name" href="/">Elham Amini<span>Founder of FYNX.</span></a><div class="social-links">{links()}</div></div><div class="footer-bottom"><span>Independent thinking. Useful work.</span><span>© 2026 Elham Amini</span><a href="#main">Back to top ↑</a></div></footer></body></html>'''
 (root/file).write_text(s)
 if not private:pages.append(url)

page('index.html','Elham Amini — Founder of FYNX | Official Website','Meet Elham Amini, founder of FYNX. Explore the mission to help retail traders, the products, founder notes and official profiles.',f'''<section class="hero shell"><div class="hero-top"><span class="eyebrow"><span class="status-dot"></span> FOUNDER / PRODUCT BUILDER</span><span class="eyebrow">IDEAS INTO USEFUL THINGS.</span></div><h1>Elham <em>Amini.</em></h1><div class="hero-bottom"><p class="hero-statement">Building a financial world<br>around the <em>retail trader.</em></p><div class="hero-intro"><p>I started FYNX to help retail traders. That purpose connects the tools I build, the ideas I explore, and the work ahead.</p><a class="button" href="/work.html">Explore my work <span>↗</span></a></div></div></section><section class="purpose"><div class="shell purpose-grid"><span class="eyebrow">01 / THE STARTING POINT</span><div><h2>A clear purpose.<br><em>A longer view.</em></h2><p>Useful tools begin with a real need. My focus with FYNX is to help independent traders learn, prepare, and make sense of their own process.</p><a class="text-link" href="/about.html">A little about me ↗</a></div><div class="monogram" aria-hidden="true"><span>EA</span><small>THINK. BUILD. REFINE.</small></div></div></section><section class="shell section"><div class="section-heading"><span class="eyebrow">02 / SELECTED WORK</span><h2>One idea.<br><em>Taking different forms.</em></h2><a class="text-link" href="/work.html">All projects ↗</a></div><div class="projects">{projects_html()}</div></section><section class="note-feature shell"><div><span class="eyebrow">03 / FOUNDER NOTES</span><h2>Why I started<br><em>FYNX.</em></h2><p>A simple starting point, and the principle I want to keep as the work grows.</p><a class="button" href="/notes/why-i-started-fynx.html">Read the note ↗</a></div><blockquote>“I started FYNX<br>to help<br><em>retail traders.</em>”<cite>Elham Amini / Founder</cite></blockquote></section><section class="contact-strip shell"><span class="eyebrow">LET’S CONNECT</span><h2>Something worth<br><em>building together?</em></h2><a class="round-link" href="/contact.html" aria-label="Contact Elham Amini">↗</a></section>''','ProfilePage')
page('about.html','About Elham Amini — The Founder Behind FYNX','Learn about Elham Amini, the purpose behind FYNX and his approach to building useful tools for retail traders.','''<section class="page-hero shell"><span class="eyebrow">THE PERSON BEHIND THE WORK</span><h1>A purpose to keep.<br><em>A world to build.</em></h1><p>I’m Elham Amini, the founder of FYNX. I started it to help retail traders.</p></section><div class="essay shell"><aside><span class="eyebrow">AT A GLANCE</span><dl><dt>NAME</dt><dd>Elham Amini</dd><dt>WORK</dt><dd>Founder & product builder</dd><dt>FOCUS</dt><dd>FYNX / Financial technology</dd></dl></aside><article><h2>The starting point</h2><p>For an independent trader, a lot of the work happens around the trade itself: understanding a market, preparing a calculation, thinking through risk, and coming back to review the decision.</p><p>FYNX brings tools and learning resources into that process. The mission is practical: give retail traders something useful to work with.</p><h2>How I think about the work</h2><p>Clarity, independence and long-term thinking connect the products. A calculator should make its inputs understandable. Research should make its sources visible. A journal should give a review somewhere to begin.</p><p>The trader’s own judgment stays at the center. Good tools can help someone ask better questions and build a process they understand.</p><h2>Building beyond a single tool</h2><p>FYNX includes Finance World, the iPhone app, developer APIs, the Journal and FYNX Funded. Each has its own role in the wider ecosystem.</p><p>The public roadmap explores the longer-term vision. It describes ambitions and direction; it does not promise dates or indicate that every proposed service is available today.</p><p><a class="text-link" href="/work.html">Explore the work ↗</a></p><h2>Find the original profiles</h2><p>You can find my LinkedIn, Instagram and GitHub below.</p><div class="social-links">'''+links()+'''</div></article></div>''','ProfilePage')
page('work.html','Elham Amini’s Work — FYNX Products & Projects','Explore products built around Elham Amini’s mission for FYNX: trading tools, the iPhone app, APIs, the Journal, Funded and the public roadmap.',f'''<section class="page-hero shell"><span class="eyebrow">THE WORK / FYNX & BEYOND</span><h1>Give the idea<br><em>something to stand on.</em></h1><p>Different products. A shared purpose: help retail traders build a more informed process.</p></section><section class="shell section work-list"><div class="projects">{projects_html()}</div></section><section class="shell other-work"><span class="eyebrow">OTHER WORK</span><h2>AI Dream Translator</h2><p>A separate app and website project from my wider product work.</p><a class="text-link" href="https://aidreamtranslator.com">Visit the project ↗</a></section>''','CollectionPage')
page('notes/why-i-started-fynx.html','Why I Started FYNX — A Note from Elham Amini','Elham Amini on starting FYNX to help retail traders and building tools with a practical purpose.', '''<section class="page-hero shell"><span class="eyebrow">FOUNDER NOTE / ELHAM AMINI</span><h1>Why I started<br><em>FYNX.</em></h1><p>A simple purpose is a useful place to begin.</p></section><div class="essay shell"><aside><span class="eyebrow">BY ELHAM AMINI</span><p>Founder of FYNX</p><a class="text-link" href="/about.html">About the author ↗</a></aside><article><p class="opening">I started FYNX to help retail traders.</p><p>That is the starting point. It gives the work a clear audience and a practical question to return to: does this help someone understand what they are doing?</p><h2>The work around the decision</h2><p>Trading involves more than an entry and an exit. There is the preparation before a decision, the calculation of risk, the context of the market, and the review afterward. Those steps need useful tools and understandable explanations.</p><p>With FYNX, I’m building around that process. A calculator gives a number a structure. A lesson gives a concept context. A journal gives a decision a record that can be revisited.</p><h2>Keep the purpose close</h2><p>The wider vision for FYNX extends beyond one product. Finance World, the app, the API and the Journal express different parts of that direction. The roadmap gives the longer-term ambitions a place to be explored.</p><p>As the work grows, the original purpose remains the reference point: help retail traders. Make the tools useful. Give people a clearer place to start.</p><p class="signature">Elham Amini</p><div class="article-next"><span class="eyebrow">CONTINUE EXPLORING</span><a href="/work.html">The products behind the idea ↗</a><a href="https://www.fynxfinanceworld.com/about.html">The FYNX story and roadmap ↗</a></div></article></div>''','BlogPosting')
page('contact.html','Contact Elham Amini — FYNX & Collaborations','Contact Elham Amini about FYNX, product ideas and collaborations. Find his official LinkedIn and Instagram profiles.', '''<section class="page-hero shell"><span class="eyebrow">A CONVERSATION STARTS HERE</span><h1>Have something<br><em>in mind?</em></h1><p>For FYNX, product ideas or a potential collaboration, send a note.</p></section><section class="contact-layout shell"><aside><h2>Find me online.</h2><div class="social-links vertical">'''+links()+'''</div><p>For app or account support, use the <a href="https://site.fynxfinanceworld.com/support.html">FYNX support page</a>.</p></aside><form action="https://formspree.io/f/mdklnaol" method="POST" accept-charset="UTF-8"><div class="form-row"><label>Your name<input name="name" autocomplete="name" required maxlength="120" placeholder="Your name"></label><label>Email address<input type="email" name="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label></div><label>Your note<textarea name="message" rows="7" required minlength="10" maxlength="10000" placeholder="Tell me what you have in mind…"></textarea></label><input type="hidden" name="_subject" value="New message for Elham Amini"><input type="hidden" name="_next" value="https://ea-la.github.io/thank-you.html"><div class="honeypot" aria-hidden="true"><label>Leave empty<input name="_gotcha" tabindex="-1" autocomplete="off"></label></div><p class="form-note">Your name, email and message are sent through Formspree so I can respond. Please leave out sensitive account information.</p><button class="button" type="submit">Send your note <span>↗</span></button></form></section>''','ContactPage')
page('thank-you.html','Message Sent — Elham Amini','Your message has been sent to Elham Amini.','<section class="page-hero shell"><span class="eyebrow">MESSAGE SENT</span><h1>Thanks for<br><em>reaching out.</em></h1><p>Your note has been sent. You can continue exploring the work below.</p><a class="button" href="/work.html">Explore the work ↗</a></section>',private=True)
page('404.html','Page Not Found — Elham Amini','Find your way back to Elham Amini’s official website.','<section class="page-hero shell"><span class="eyebrow">404 / PAGE NOT FOUND</span><h1>A different<br><em>way forward.</em></h1><p>This page could not be found.</p><a class="button" href="/">Back to the website ↗</a></section>',private=True)
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in pages)+'</urlset>\n')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'/sitemap.xml\n')
(root/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#193e32"/><text x="9" y="43" font-family="Georgia,serif" font-size="37" fill="#f5f3eb">ea</text></svg>')
print('Built',len(pages),'public pages and two noindex utility pages.')
